# Stage 2 triage spec: groups by root cause.
SEEDS = {
 "SEED-L1": "Listener.listener_loop catches only TimeoutError, CancelledError and ConnectionClosed. Any other exception from _receive_message (e.g. websockets ConcurrencyError, json decode error) kills the listener task silently, and in-flight sends hang.",
 "SEED-C1": "On ConnectionClosed the listener does not reset connection.websocket, so Connection.aopen never reconnects (websocket is not None, so it skips the connect).",
 "SEED-C2": "aclose() during a connect that is still in progress does nothing (websocket is still None), and the connection opens after the 'close'.",
 "SEED-C3": "A send() cancelled by wait_for leaves its Transaction in conn.mapper until a reply arrives or the connection closes.",
 "SEED-G1": "Browser.get(new_tab=True) timing out after Target.createTarget leaves an orphaned tab (the target was created but the caller never gets it and nothing closes it).",
 "SEED-X1": "Connection._register_handlers has a bare `except:` around `await self.send(domain_mod.enable(), _is_update=True)` that swallows CancelledError, so a wait_for timeout / task.cancel() hitting that await is silently ignored and the outer send continues.",
 "SEED-X2": "Broad excepts in element.py (Element.click: `try: await self.flash() except: pass`) swallow CancelledError the same way.",
 "SEED-X3": "Broad except in proxy.py (UpstreamProxy.open_tunnel: `except BaseException as e`) around awaits: check whether it swallows CancelledError (it may re-raise; verify).",
 "SEED-K1": "Config.browser_args property neither merges --disable-features nor removes duplicates, so it differs from what Config() (__call__) returns.",
 "SEED-K2": "User browser_args that repeat flags Config adds itself (--headless=new, --no-sandbox, --lang, --disable-webgl, webrtc flags) are not deduplicated in Config.__call__.",
 "SEED-K3": "Browser.start calls config.add_argument('--load-extension=...') every start, so a Config/Browser that is started again gets --load-extension appended again (duplicate flags).",
 "SEED-K4": "Config keeps a reference to the caller's browser_args list (self._browser_args = browser_args), so Config.add_argument mutates the caller's list.",
 "SEED-K5": "Config.add_argument rejects any arg that contains 'lang' or 'headless' (etc.) anywhere, e.g. --disable-features=LanguageDetectionAPI or --accept-lang... is rejected with ValueError.",
}

